async def hydrate(state, runtime: Runtime[Bridge]):
    return await operation(state, runtime, 'sync', 'materials')

async def model(state, runtime: Runtime[Bridge]):
    return await operation(state, runtime, 'model', 'model')

async def retrieve(state, runtime: Runtime[Bridge]):
    return await operation(state, runtime, 'tool', 'retrieve')

async def validate(state, runtime: Runtime[Bridge]):
    return await operation(state, runtime, 'tool', 'validate')

async def review_answer(state, runtime: Runtime[Bridge]):
    return await operation(state, runtime, 'tool', 'review_answer')

async def question(state, runtime: Runtime[Bridge]):
    return await operation(state, runtime, 'tool', 'question')

def wait_input(state):
    # This node is deliberately side-effect-free before interrupt: resume
    # re-enters it. A reviewed child revision continues with fresh Go scope.
    value = interrupt({'kind': 'clarification', 'question': state['view']['preparation']['question']})
    return {'continuation': value['execution_id'], 'last_node': 'continued'}

def wait_recovery(state):
    value = interrupt({'kind': 'recovery', 'provider_state': state['view']['preparation']['provider_state']})
    return {'view': value['view'], 'last_node': 'resumed'}

def feedback(state):
    # Inputs are already re-reviewed by Go. This node records the parent
    # revision explicitly rather than treating feedback as new source facts.
    return {'last_node': 'feedback'}

def route(state):
    view = state['view']
    prep = view['preparation']
    if prep.get('question'):
        return 'wait_input'
    if view['phase'] == 'PAUSED':
        return 'wait_recovery'
    if view['phase'] != 'RUNNING':
        return END
    pending = view.get('pending')
    if pending == 'ask_preparation_question':
        return 'question'
    if pending == 'finish_preparation_plan':
        return 'validate'
    if pending == 'finish_project_defense_review':
        return 'review_answer'
    if pending:
        return 'retrieve'
    return 'model'

func (g *PreparationGraphClient) InternalStep(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "no-store")
	capability := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
	g.mu.Lock()
	s := g.sessions[capability]
	g.mu.Unlock()
	if s == nil {
		http.Error(w, "invalid execution capability", 401)
		return
	}
	var in struct {
		Action   string `json:"action"`
		Sequence int    `json:"sequence"`
	}
	dec := json.NewDecoder(io.LimitReader(r.Body, 1025))
	dec.DisallowUnknownFields()
	if dec.Decode(&in) != nil || in.Sequence < 0 || (in.Action != "sync" && in.Action != "model" && in.Action != "tool") {
		http.Error(w, "invalid operation", 400)
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed || s.ctx.Err() != nil {
		http.Error(w, "execution stopped", 409)
		return
	}
	// Replayed nodes receive the durable receipt, not another provider call/read.
	if in.Action == "sync" || in.Sequence < s.v.Preparation.GraphSequence {
		json.NewEncoder(w).Encode(preparationGraphSnapshot(s.v))
		return
	}
	if in.Sequence != s.v.Preparation.GraphSequence || s.v.State != "RUNNING" {
		http.Error(w, "stale graph cursor", 409)
		return
	}
	if s.v.Preparation.ProviderState != "READY" {
		http.Error(w, "model outcome unknown", 409)
		return
	}
	ctx, cancel := context.WithCancel(s.ctx)
	defer cancel()
	stop := context.AfterFunc(r.Context(), cancel)
	defer stop()
	// Fence every operation before dispatch, including reads and model admission.
	if err := s.checkpoint(); err != nil {
		http.Error(w, "stale execution", 409)
		return
	}
	var checkpointErr error
	persist := func() error {
		err := s.checkpoint()
		if err != nil {
			checkpointErr = err
		}
		return err
	}
	err := runPreparationStep(ctx, s.user, s.v, s.model, s.tools, persist, in.Action)
	if checkpointErr != nil {
		http.Error(w, "checkpoint not durable", 409)
		return
	}
	if err != nil && s.v.State == "RUNNING" {
		s.v.State = "PAUSED"
		s.v.Answer = "执行中断，已完成步骤已保存。"
		if s.v.Preparation.ProviderState == "DISPATCHED" {
			s.v.Preparation.ProviderState = "UNKNOWN"
		}
		if !errors.Is(err, context.Canceled) && !errors.Is(err, context.DeadlineExceeded) {
			s.v.Answer = "本轮未完成，请检查执行过程后继续。"
		}
		// A failed SQL fence must never be turned into a successful graph response.
		if saveErr := s.checkpoint(); saveErr != nil {
			http.Error(w, "execution fenced", 409)
			return
		}
	}
	json.NewEncoder(w).Encode(preparationGraphSnapshot(s.v))

func savePreparationTx(ctx context.Context, tx *sql.Tx, user string, a SavePreparationArgs) (json.RawMessage, error) {
	v, err := One[AgentExecution](ctx, tx, "SELECT body FROM agent_executions WHERE id=? AND user_id=? FOR UPDATE", a.ExecutionID, user)
	if err != nil {
		return nil, err
	}
	state := v.Preparation
	if state != nil && state.Defense != nil && (a.EvidenceVersion != state.Defense.Version || state.Defense.Version != projectdefense.Version()) {
		return nil, ErrStaleInput
	}
	if v.State != "COMPLETED" || state == nil || state.Plan == nil || state.Revision != a.Revision || d.Hash(d.JSON(state.Plan)) != a.PlanHash {
		return nil, ErrConflict
	}
	app, err := One[d.Application](ctx, tx, "SELECT body FROM applications WHERE id=? AND user_id=? FOR UPDATE", state.Input.ApplicationID, user)
	if err != nil {
		return nil, err
	}
	if app.Version != a.ApplicationVersion {
		return nil, ErrConflict
	}
	identity, _, err := preparationAgentIdentityQuery(ctx, tx, user, state.Input.ApplicationID, state.Input.OtherReviews)
	if err != nil {
		return nil, err
	}
	if identity != v.SourceIdentity {
		return nil, ErrStaleInput
	}

	if state.SavedAt == nil {
		now := time.Now().UTC()
		state.SavedAt = &now
		_, err = tx.ExecContext(ctx, "UPDATE agent_executions SET body=? WHERE id=? AND user_id=? AND state='COMPLETED'", d.JSON(v), v.ID, user)
		if err != nil {
			return nil, err
		}
	}
	return json.RawMessage(d.JSON(map[string]any{"execution_id": v.ID, "application_id": app.ID, "revision": state.Revision, "saved_at": state.SavedAt, "plan": state.Plan})), nil
}

// Replayed nodes receive the durable receipt, not another provider call/read.
if in.Action == "sync" || in.Sequence < s.v.Preparation.GraphSequence {
	json.NewEncoder(w).Encode(preparationGraphSnapshot(s.v))
	return
}
if in.Sequence != s.v.Preparation.GraphSequence || s.v.State != "RUNNING" {
	http.Error(w, "stale graph cursor", 409)
	return
}
if s.v.Preparation.ProviderState != "READY" {
	http.Error(w, "model outcome unknown", 409)
	return
}

if claim != nil && !claim.RetryUnknown && ((v.Narration != nil && (v.Narration.ProviderState == "DISPATCHED" || v.Narration.ProviderState == "UNKNOWN")) || (v.Preparation != nil && (v.Preparation.ProviderState == "DISPATCHED" || v.Preparation.ProviderState == "UNKNOWN"))) {
	return ErrConflict
}
var running int
if e := tx.QueryRowContext(ctx, "SELECT COUNT(*) FROM agent_executions WHERE user_id=? AND id<>? AND state='RUNNING' AND lease_until>UTC_TIMESTAMP(6)", user, id).Scan(&running); e != nil {
	return e
}
if running >= 2 {
	return ErrConflict
}
if v.Resumes >= MaxAgentExecutionAttempts {
	v.State = "FAILED"
	v.Answer = "已达到本次任务的尝试上限，请核对原因后发起新任务。"
	token = ""
	_, e := tx.ExecContext(ctx, "UPDATE agent_executions SET state='FAILED',lease_token='',lease_until=NULL,body=? WHERE id=? AND user_id=?", d.JSON(v), id, user)
	return e
}

func TestPreparationUnknownModelAndDurablePendingTools(t *testing.T) {
	t.Run("unknown_model_no_internal_retry", func(t *testing.T) {
		v := p.AgentExecution{State: "RUNNING", Preparation: prepTestState()}
		calls := 0
		err := RunPreparationLoop(context.Background(), "owner", &v, prepModelFunc(func(context.Context, []Message, []Definition) (Reply, error) {
			calls++
			return Reply{}, errors.New("provider disconnected")
		}), nil, func() error { return nil })
		if err == nil || calls != 1 || v.State != "PAUSED" || v.Preparation.ProviderState != "UNKNOWN" {
			t.Fatal(v, err, calls)
		}
	})
	t.Run("resume_completed_reads_without_replay", func(t *testing.T) {
		state := prepTestState()
		v := p.AgentExecution{State: "RUNNING", Preparation: state, Next: 1, Calls: []p.ExecutionCall{{ID: "done", Name: "search_preparation_knowledge", Args: json.RawMessage(`{"query":"already-read"}`)}, {ID: "pending", Name: "search_preparation_knowledge", Args: json.RawMessage(`{"query":"Go"}`)}}}
		tools := 0
		toolset := prepToolsFunc(func(ctx context.Context, user, name string, args json.RawMessage) (any, error) {
			if strings.Contains(string(args), "already-read") {
				t.Fatal("completed read repeated")
			}
			tools++
			return []d.PreparationSource{}, nil
		})
		model := prepModelFunc(func(context.Context, []Message, []Definition) (Reply, error) {
			return Reply{Calls: []Call{{ID: "finish", Name: "finish_preparation_plan", Args: json.RawMessage(d.JSON(prepTestPlan(state)))}}}, nil
		})
		if err := RunPreparationLoop(context.Background(), "owner", &v, model, toolset, func() error { return nil }); err != nil {
			t.Fatal(err)
		}
		if tools != 1 || v.State != "COMPLETED" {
			t.Fatal(v, tools)
		}
	})
}
